const domains = $input.all().map(r => r.json).filter(r => r.domain);
const today = new Date();
today.setHours(0,0,0,0);
const results = [];

for (const row of domains) {
  const domain = row.domain.trim().toLowerCase();
  const expiryDate = row.expiry_date ? new Date(row.expiry_date) : null;
  const autoRenew = row.auto_renew === 'TRUE' || row.auto_renew === true;
  const registrar = row.registrar || '';
  const owner = row.owner || '';
  const notes = row.notes || '';
  const alertSentDays = row.last_alert_days ? parseInt(row.last_alert_days) : null;

  if (!expiryDate || isNaN(expiryDate)) {
    results.push({ domain, status: 'unknown_expiry', registrar, owner, notes, autoRenew });
    continue;
  }

  const daysUntilExpiry = Math.floor((expiryDate - today) / 86400000);
  let urgency = 'ok';
  if (daysUntilExpiry < 0) urgency = 'expired';
  else if (daysUntilExpiry <= 7) urgency = 'critical';
  else if (daysUntilExpiry <= 30) urgency = 'urgent';
  else if (daysUntilExpiry <= 60) urgency = 'warning';
  else if (daysUntilExpiry <= 90) urgency = 'notice';

  const shouldAlert = ['expired','critical','urgent'].includes(urgency) ||
    (urgency === 'warning' && alertSentDays !== 30) ||
    (urgency === 'notice' && alertSentDays !== 60);

  if (urgency !== 'ok' || shouldAlert) {
    results.push({ domain, expiryDate: expiryDate.toISOString().split('T')[0], daysUntilExpiry, urgency, autoRenew, registrar, owner, notes, shouldAlert });
  }
}

results.sort((a,b) => (a.daysUntilExpiry||999) - (b.daysUntilExpiry||999));
const critical = results.filter(d => ['expired','critical'].includes(d.urgency));
const needsAction = results.filter(d => !d.autoRenew && d.urgency !== 'ok');

return [{ json: { domains: results, critical, needsAction, totalMonitored: domains.length, scanDate: today.toISOString().split('T')[0] } }];

